<?php $this->layout('default', ['title' => 'Conteúdos | Realizze', 'description' => 'Artigos e novidades do Realizze sobre organização financeira.']); ?>
<section class="page-hero"><div class="container narrow"><span class="eyebrow">CONTEÚDOS</span><h1>Boas ideias para organizar suas finanças.</h1></div></section>
<section class="section"><?php if ($result['rows'] === []): ?><div class="container"><p class="rz-empty">Novos conteúdos serão publicados em breve.</p></div><?php else: ?><div class="container blog-grid"><?php foreach ($result['rows'] as $post): ?>
<article class="post-card"><?php if ($post['cover']): ?><img class="rz-post-cover" src="<?= $this->e($post['cover']) ?>" alt="" loading="lazy"><?php endif; ?><div class="post-body"><span class="eyebrow"><?= $this->e($post['category_title'] ?? ($post['post_type'] === 'news' ? 'Notícia' : 'Artigo')) ?></span><h2><a href="/blog/<?= $this->e($post['uri']) ?>"><?= $this->e($post['title']) ?></a></h2><p><?= $this->e($post['subtitle']) ?></p></div></article>
<?php endforeach; ?></div><?php if ($result['pages'] > 1): ?><nav class="container rz-pager" aria-label="Paginação"><?php if ($result['page'] > 1): ?><a class="btn btn-outline" href="/blog?pagina=<?= (int) $result['page'] - 1 ?>">Anteriores</a><?php endif; ?><?php if ($result['page'] < $result['pages']): ?><a class="btn btn-outline" href="/blog?pagina=<?= (int) $result['page'] + 1 ?>">Próximos</a><?php endif; ?></nav><?php endif; ?><?php endif; ?></section>
